from claude_agent_sdk import tool, create_sdk_mcp_server, ClaudeAgentOptions

@tool("lookup_price", "Look up the current price for a SKU", {"sku": str})
async def lookup_price(args):
    try:
        price = await pricing_service.get(args["sku"])
        return {"content": [{"type": "text", "text": f"{args['sku']}: {price}"}]}
    except ServiceError as e:
        # Tell the loop the tool failed so Claude can recover or explain
        return {"content": [{"type": "text", "text": str(e)}], "is_error": True}

async def block_destructive(input_data, tool_use_id, context):
    cmd = (input_data.get("tool_input") or {}).get("command", "")
    if any(k in cmd.upper() for k in ("DROP ", "TRUNCATE ", "DELETE FROM")):
        return {"hookSpecificOutput": {"hookEventName": "PreToolUse",
                                         "permissionDecision": "deny",
                                         "permissionDecisionReason": "Destructive SQL blocked by policy"}}
    return {}

options = ClaudeAgentOptions(
    mcp_servers={"pricing": create_sdk_mcp_server("pricing", tools=[lookup_price])},
    allowed_tools=["mcp__pricing__lookup_price", "Read"],
    hooks={"PreToolUse": [{"matcher": "Bash", "hooks": [block_destructive]}]},
)
